CREATE TABLE IF NOT EXISTS wall_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),author_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,body varchar(2000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT wall_post_body_nonblank CHECK(length(btrim(body))>0));
CREATE INDEX IF NOT EXISTS wall_posts_author_time_idx ON wall_posts(author_id,created_at DESC,id DESC);CREATE INDEX IF NOT EXISTS wall_posts_feed_idx ON wall_posts(created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS wall_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),post_id uuid NOT NULL REFERENCES wall_posts(id) ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,body varchar(1000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT wall_comment_body_nonblank CHECK(length(btrim(body))>0));CREATE INDEX IF NOT EXISTS wall_comments_post_time_idx ON wall_comments(post_id,created_at ASC);
CREATE TABLE IF NOT EXISTS wall_likes(post_id uuid NOT NULL REFERENCES wall_posts(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(post_id,user_id));CREATE INDEX IF NOT EXISTS wall_likes_post_idx ON wall_likes(post_id);
